import generateModule from "@babel/generator";
import { parse } from "./parse.js";

const generate = generateModule.default || generateModule;

/**
 * Formatting Architecture:
 *
 * 1. Parse source code into an AST using @babel/parser.
 * 2. Convert AST nodes into an intermediate Document representation (text, concat,
 *    indent, line) inspired by Prettier's doc builder.
 * 3. Render the document into a formatted string with scaled indentation and
 *    clean line breaks.
 * 4. Gracefully fall back to @babel/generator for any rare or unhandled syntax
 *    nodes, ensuring production-scale multi-thousand-line files never crash.
 */

function text(value) {
  return { type: "text", value };
}

function concat(parts) {
  return { type: "concat", parts };
}

function indent(contents) {
  return { type: "indent", contents };
}

function line() {
  return { type: "line" };
}

function renderDoc(doc, options = {}) {
  const indentUnit = options.indentUnit ?? "  ";
  let output = "";
  let currentIndent = 0;
  let isStartOfLine = true;

  function render(node) {
    if (!node) return;

    switch (node.type) {
      case "text":
        if (node.value.length === 0) return;
        if (isStartOfLine) {
          output += indentUnit.repeat(currentIndent);
          isStartOfLine = false;
        }
        output += node.value;
        break;

      case "concat":
        for (const part of node.parts) {
          render(part);
        }
        break;

      case "indent":
        currentIndent++;
        render(node.contents);
        currentIndent--;
        break;

      case "line":
        output += "\n";
        isStartOfLine = true;
        break;
    }
  }

  render(doc);
  return output;
}

function resolveOptions(options = {}) {
  const quotes = options.quotes ?? "single";
  const semi = options.semi ?? true;

  if (!["single", "double"].includes(quotes)) {
    throw new Error('The "quotes" option must be "single" or "double".');
  }

  if (typeof semi !== "boolean") {
    throw new Error('The "semi" option must be true or false.');
  }

  return { quotes, semi };
}

function fallbackPrint(node, options) {
  try {
    const raw = generate(node, {
      quotes: options.quotes,
      retainLines: false,
      compact: false,
    }).code;
    return text(raw);
  } catch {
    throw new Error(`Unsupported syntax node: ${node.type}`);
  }
}

function printStringLiteral(node, options) {
  if (options.quotes === "double" || node.value.includes("'")) {
    const escapedValue = node.value.replaceAll("\\", "\\\\").replaceAll('"', '\\"');
    return text(`"${escapedValue}"`);
  }

  const escapedValue = node.value.replaceAll("\\", "\\\\").replaceAll("'", "\\'");
  return text(`'${escapedValue}'`);
}

function printMemberExpression(node, options) {
  return concat([
    printExpression(node.object, options),
    text(node.computed ? "[" : "."),
    node.computed ? printExpression(node.property, options) : text(node.property.name),
    text(node.computed ? "]" : ""),
  ]);
}

function printCallExpression(node, options) {
  const argDocs = [];
  node.arguments.forEach((arg, index) => {
    if (index > 0) {
      argDocs.push(text(", "));
    }
    argDocs.push(printExpression(arg, options));
  });

  return concat([
    printExpression(node.callee, options),
    text("("),
    ...argDocs,
    text(")"),
  ]);
}

function printNewExpression(node, options) {
  const argDocs = [];
  node.arguments.forEach((arg, index) => {
    if (index > 0) {
      argDocs.push(text(", "));
    }
    argDocs.push(printExpression(arg, options));
  });

  return concat([
    text("new "),
    printExpression(node.callee, options),
    text("("),
    ...argDocs,
    text(")"),
  ]);
}

function printBinaryExpression(node, options) {
  return concat([
    printExpression(node.left, options),
    text(` ${node.operator} `),
    printExpression(node.right, options),
  ]);
}

function printUnaryExpression(node, options) {
  const needsSpace = ["typeof", "void", "delete"].includes(node.operator);
  return concat([
    text(node.operator + (needsSpace ? " " : "")),
    printExpression(node.argument, options),
  ]);
}

function printUpdateExpression(node, options) {
  if (node.prefix) {
    return concat([text(node.operator), printExpression(node.argument, options)]);
  }
  return concat([printExpression(node.argument, options), text(node.operator)]);
}

function printAssignmentExpression(node, options) {
  return concat([
    printExpression(node.left, options),
    text(` ${node.operator} `),
    printExpression(node.right, options),
  ]);
}

function printLogicalExpression(node, options) {
  return concat([
    printExpression(node.left, options),
    text(` ${node.operator} `),
    printExpression(node.right, options),
  ]);
}

function printConditionalExpression(node, options) {
  return concat([
    printExpression(node.test, options),
    text(" ? "),
    printExpression(node.consequent, options),
    text(" : "),
    printExpression(node.alternate, options),
  ]);
}

function printArrowFunctionExpression(node, options) {
  const paramDocs = [];
  node.params.forEach((param, index) => {
    if (index > 0) {
      paramDocs.push(text(", "));
    }
    paramDocs.push(printExpression(param, options));
  });

  const paramsDoc =
    node.params.length === 1 && node.params[0].type === "Identifier"
      ? text(node.params[0].name)
      : concat([text("("), ...paramDocs, text(")")]);

  const bodyDoc =
    node.body.type === "BlockStatement"
      ? printBlockStatement(node.body, options)
      : printExpression(node.body, options);

  return concat([paramsDoc, text(" => "), bodyDoc]);
}

function printFunctionExpression(node, options) {
  const paramDocs = [];
  node.params.forEach((param, index) => {
    if (index > 0) {
      paramDocs.push(text(", "));
    }
    paramDocs.push(printExpression(param, options));
  });

  return concat([
    text(`function${node.id ? ` ${node.id.name}` : ""}(`),
    ...paramDocs,
    text(") "),
    printBlockStatement(node.body, options),
  ]);
}

function printObjectProperty(node, options) {
  const keyDoc = node.computed
    ? concat([text("["), printExpression(node.key, options), text("]")])
    : node.key.type === "Identifier"
      ? text(node.key.name)
      : printExpression(node.key, options);

  if (node.shorthand) {
    return keyDoc;
  }

  return concat([keyDoc, text(": "), printExpression(node.value, options)]);
}

function printObjectExpression(node, options) {
  if (node.properties.length === 0) {
    return text("{}");
  }

  const isMultiLine =
    node.properties.length > 2 ||
    Boolean(node.loc && node.loc.start.line !== node.loc.end.line);

  if (!isMultiLine) {
    const propDocs = [];
    node.properties.forEach((prop, i) => {
      if (i > 0) propDocs.push(text(", "));
      if (prop.type === "ObjectProperty") {
        propDocs.push(printObjectProperty(prop, options));
      } else if (prop.type === "SpreadElement") {
        propDocs.push(concat([text("..."), printExpression(prop.argument, options)]));
      } else {
        propDocs.push(fallbackPrint(prop, options));
      }
    });
    return concat([text("{ "), concat(propDocs), text(" }")]);
  }

  const propDocs = [];
  node.properties.forEach((prop, i) => {
    if (i > 0) {
      propDocs.push(text(","));
      propDocs.push(line());
    }
    if (prop.type === "ObjectProperty") {
      propDocs.push(printObjectProperty(prop, options));
    } else if (prop.type === "SpreadElement") {
      propDocs.push(concat([text("..."), printExpression(prop.argument, options)]));
    } else {
      propDocs.push(fallbackPrint(prop, options));
    }
  });

  return concat([
    text("{"),
    indent(concat([line(), concat(propDocs)])),
    line(),
    text("}"),
  ]);
}

function printArrayExpression(node, options) {
  if (node.elements.length === 0) {
    return text("[]");
  }

  const isMultiLine =
    node.elements.length > 3 ||
    Boolean(node.loc && node.loc.start.line !== node.loc.end.line);

  if (!isMultiLine) {
    const elemDocs = [];
    node.elements.forEach((elem, i) => {
      if (i > 0) elemDocs.push(text(", "));
      elemDocs.push(elem ? printExpression(elem, options) : text(""));
    });
    return concat([text("["), concat(elemDocs), text("]")]);
  }

  const elemDocs = [];
  node.elements.forEach((elem, i) => {
    if (i > 0) {
      elemDocs.push(text(","));
      elemDocs.push(line());
    }
    elemDocs.push(elem ? printExpression(elem, options) : text(""));
  });

  return concat([
    text("["),
    indent(concat([line(), concat(elemDocs)])),
    line(),
    text("]"),
  ]);
}

function printTemplateLiteral(node, options) {
  const parts = [text("`")];
  node.quasis.forEach((quasi, index) => {
    parts.push(text(quasi.value.raw));
    if (index < node.expressions.length) {
      parts.push(text("${"));
      parts.push(printExpression(node.expressions[index], options));
      parts.push(text("}"));
    }
  });
  parts.push(text("`"));
  return concat(parts);
}

function printExpression(node, options) {
  let doc;

  switch (node.type) {
    case "StringLiteral":
      doc = printStringLiteral(node, options);
      break;
    case "NumericLiteral":
      doc = text(node.extra?.raw ?? String(node.value));
      break;
    case "BooleanLiteral":
      doc = text(String(node.value));
      break;
    case "NullLiteral":
      doc = text("null");
      break;
    case "Identifier":
      doc = text(node.name);
      break;
    case "ThisExpression":
      doc = text("this");
      break;
    case "Super":
      doc = text("super");
      break;
    case "BinaryExpression":
      doc = printBinaryExpression(node, options);
      break;
    case "UnaryExpression":
      doc = printUnaryExpression(node, options);
      break;
    case "UpdateExpression":
      doc = printUpdateExpression(node, options);
      break;
    case "AssignmentExpression":
      doc = printAssignmentExpression(node, options);
      break;
    case "LogicalExpression":
      doc = printLogicalExpression(node, options);
      break;
    case "ConditionalExpression":
      doc = printConditionalExpression(node, options);
      break;
    case "MemberExpression":
      doc = printMemberExpression(node, options);
      break;
    case "CallExpression":
      doc = printCallExpression(node, options);
      break;
    case "NewExpression":
      doc = printNewExpression(node, options);
      break;
    case "ObjectExpression":
      doc = printObjectExpression(node, options);
      break;
    case "ArrayExpression":
      doc = printArrayExpression(node, options);
      break;
    case "ArrowFunctionExpression":
      doc = printArrowFunctionExpression(node, options);
      break;
    case "FunctionExpression":
      doc = printFunctionExpression(node, options);
      break;
    case "TemplateLiteral":
      doc = printTemplateLiteral(node, options);
      break;
    case "SpreadElement":
    case "RestElement":
      doc = concat([text("..."), printExpression(node.argument, options)]);
      break;
    case "AwaitExpression":
      doc = concat([text("await "), printExpression(node.argument, options)]);
      break;
    default:
      doc = fallbackPrint(node, options);
      break;
  }

  if (node.extra?.parenthesized) {
    return concat([text("("), doc, text(")")]);
  }

  return doc;
}

function printVariableDeclarator(declarator, options) {
  if (declarator.id.type !== "Identifier") {
    return fallbackPrint(declarator, options);
  }

  if (!declarator.init) {
    return text(declarator.id.name);
  }

  return concat([
    text(declarator.id.name),
    text(" = "),
    printExpression(declarator.init, options),
  ]);
}

function printVariableDeclaration(node, options) {
  if (!["const", "let", "var"].includes(node.kind)) {
    throw new Error(`Unsupported variable declaration kind: ${node.kind}`);
  }

  const parts = [text(`${node.kind} `)];

  node.declarations.forEach((decl, index) => {
    if (index > 0) {
      parts.push(text(", "));
    }
    parts.push(printVariableDeclarator(decl, options));
  });

  if (options.semi) {
    parts.push(text(";"));
  }

  return concat(parts);
}

function printBlockStatement(node, options) {
  const nonEmpties = node.body.filter((stmt) => stmt.type !== "EmptyStatement");
  if (nonEmpties.length === 0) {
    return text("{}");
  }

  const parts = [];
  nonEmpties.forEach((stmt, index) => {
    if (index > 0) {
      parts.push(line());
      const prev = nonEmpties[index - 1];
      if (
        (stmt.loc && prev.loc && stmt.loc.start.line - prev.loc.end.line > 1) ||
        stmt.type === "FunctionDeclaration" ||
        prev.type === "FunctionDeclaration" ||
        stmt.type === "ClassDeclaration" ||
        prev.type === "ClassDeclaration"
      ) {
        parts.push(line());
      }
    }
    parts.push(printStatement(stmt, options));
  });

  return concat([
    text("{"),
    indent(concat([line(), concat(parts)])),
    line(),
    text("}"),
  ]);
}

function printIfStatement(node, options) {
  const parts = [
    text("if ("),
    printExpression(node.test, options),
    text(") "),
    printStatement(node.consequent, options),
  ];

  if (node.alternate) {
    parts.push(text(" else "));
    parts.push(printStatement(node.alternate, options));
  }

  return concat(parts);
}

function printForStatement(node, options) {
  let initDoc = text("");
  if (node.init) {
    if (node.init.type === "VariableDeclaration") {
      const parts = [text(`${node.init.kind} `)];
      node.init.declarations.forEach((decl, index) => {
        if (index > 0) parts.push(text(", "));
        parts.push(printVariableDeclarator(decl, options));
      });
      initDoc = concat(parts);
    } else {
      initDoc = printExpression(node.init, options);
    }
  }

  const testDoc = node.test ? printExpression(node.test, options) : text("");
  const updateDoc = node.update ? printExpression(node.update, options) : text("");

  return concat([
    text("for ("),
    initDoc,
    text("; "),
    testDoc,
    text("; "),
    updateDoc,
    text(") "),
    printStatement(node.body, options),
  ]);
}

function printWhileStatement(node, options) {
  return concat([
    text("while ("),
    printExpression(node.test, options),
    text(") "),
    printStatement(node.body, options),
  ]);
}

function printFunctionDeclaration(node, options) {
  const paramDocs = [];
  node.params.forEach((param, index) => {
    if (index > 0) {
      paramDocs.push(text(", "));
    }
    paramDocs.push(printExpression(param, options));
  });

  return concat([
    text(`function ${node.id ? node.id.name : ""}(`),
    ...paramDocs,
    text(") "),
    printBlockStatement(node.body, options),
  ]);
}

function printClassMethod(node, options) {
  const parts = [];
  if (node.static) parts.push(text("static "));
  if (node.async) parts.push(text("async "));
  if (node.kind === "get" || node.kind === "set") parts.push(text(`${node.kind} `));

  const keyDoc = node.computed
    ? concat([text("["), printExpression(node.key, options), text("]")])
    : text(node.key.name);

  parts.push(keyDoc);

  const paramDocs = [];
  node.params.forEach((param, index) => {
    if (index > 0) {
      paramDocs.push(text(", "));
    }
    paramDocs.push(printExpression(param, options));
  });

  parts.push(text("("));
  parts.push(...paramDocs);
  parts.push(text(") "));
  parts.push(printBlockStatement(node.body, options));

  return concat(parts);
}

function printClassProperty(node, options) {
  const parts = [];
  if (node.static) parts.push(text("static "));

  const keyDoc = node.computed
    ? concat([text("["), printExpression(node.key, options), text("]")])
    : text(node.key.name);

  parts.push(keyDoc);

  if (node.value) {
    parts.push(text(" = "));
    parts.push(printExpression(node.value, options));
  }

  if (options.semi) {
    parts.push(text(";"));
  }

  return concat(parts);
}

function printClassBody(node, options) {
  if (node.body.length === 0) {
    return text("{}");
  }

  const parts = [];
  node.body.forEach((member, index) => {
    if (index > 0) {
      parts.push(line());
      const prev = node.body[index - 1];
      if (
        (member.loc && prev.loc && member.loc.start.line - prev.loc.end.line > 1) ||
        member.type === "ClassMethod" ||
        prev.type === "ClassMethod"
      ) {
        parts.push(line());
      }
    }
    if (member.type === "ClassMethod") {
      parts.push(printClassMethod(member, options));
    } else if (member.type === "ClassProperty" || member.type === "PropertyDefinition") {
      parts.push(printClassProperty(member, options));
    } else {
      parts.push(fallbackPrint(member, options));
    }
  });

  return concat([
    text("{"),
    indent(concat([line(), concat(parts)])),
    line(),
    text("}"),
  ]);
}

function printClassDeclaration(node, options) {
  const parts = [text("class ")];

  if (node.id) {
    parts.push(text(`${node.id.name} `));
  }

  if (node.superClass) {
    parts.push(text("extends "));
    parts.push(printExpression(node.superClass, options));
    parts.push(text(" "));
  }

  parts.push(printClassBody(node.body, options));
  return concat(parts);
}

function printImportDeclaration(node, options) {
  const parts = [text("import ")];

  if (node.specifiers.length > 0) {
    const defaultSpec = node.specifiers.find((s) => s.type === "ImportDefaultSpecifier");
    const namespaceSpec = node.specifiers.find((s) => s.type === "ImportNamespaceSpecifier");
    const namedSpecs = node.specifiers.filter((s) => s.type === "ImportSpecifier");

    const specParts = [];
    if (defaultSpec) {
      specParts.push(text(defaultSpec.local.name));
    }
    if (namespaceSpec) {
      specParts.push(text(`* as ${namespaceSpec.local.name}`));
    }
    if (namedSpecs.length > 0) {
      const namedDocs = [];
      namedSpecs.forEach((s, i) => {
        if (i > 0) namedDocs.push(text(", "));
        if (s.imported.name === s.local.name) {
          namedDocs.push(text(s.imported.name));
        } else {
          namedDocs.push(text(`${s.imported.name} as ${s.local.name}`));
        }
      });
      specParts.push(concat([text("{ "), concat(namedDocs), text(" }")]));
    }

    parts.push(concat(specParts));
    parts.push(text(" from "));
  }

  parts.push(printStringLiteral(node.source, options));
  if (options.semi) {
    parts.push(text(";"));
  }

  return concat(parts);
}

function printExportNamedDeclaration(node, options) {
  if (node.declaration) {
    return concat([text("export "), printStatement(node.declaration, options)]);
  }

  const specDocs = [];
  node.specifiers.forEach((s, i) => {
    if (i > 0) specDocs.push(text(", "));
    if (s.local.name === s.exported.name) {
      specDocs.push(text(s.local.name));
    } else {
      specDocs.push(text(`${s.local.name} as ${s.exported.name}`));
    }
  });

  return concat([
    text("export { "),
    concat(specDocs),
    text(" }"),
    text(options.semi ? ";" : ""),
  ]);
}

function printExportDefaultDeclaration(node, options) {
  if (
    node.declaration.type === "ClassDeclaration" ||
    node.declaration.type === "FunctionDeclaration"
  ) {
    return concat([text("export default "), printStatement(node.declaration, options)]);
  }

  return concat([
    text("export default "),
    printExpression(node.declaration, options),
    text(options.semi ? ";" : ""),
  ]);
}

function printTryStatement(node, options) {
  const parts = [text("try "), printBlockStatement(node.block, options)];

  if (node.handler) {
    parts.push(text(" catch"));
    if (node.handler.param) {
      parts.push(text(" ("));
      parts.push(printExpression(node.handler.param, options));
      parts.push(text(")"));
    }
    parts.push(text(" "));
    parts.push(printBlockStatement(node.handler.body, options));
  }

  if (node.finalizer) {
    parts.push(text(" finally "));
    parts.push(printBlockStatement(node.finalizer, options));
  }

  return concat(parts);
}

function printThrowStatement(node, options) {
  return concat([
    text("throw "),
    printExpression(node.argument, options),
    text(options.semi ? ";" : ""),
  ]);
}

function printSwitchCase(node, options) {
  const label = node.test
    ? concat([text("case "), printExpression(node.test, options), text(":")])
    : text("default:");

  if (node.consequent.length === 0) {
    return label;
  }

  const consDocs = [];
  node.consequent.forEach((stmt) => {
    consDocs.push(line());
    consDocs.push(printStatement(stmt, options));
  });

  return concat([label, indent(concat(consDocs))]);
}

function printSwitchStatement(node, options) {
  const cases = [];
  node.cases.forEach((c, i) => {
    if (i > 0) cases.push(line());
    cases.push(printSwitchCase(c, options));
  });

  return concat([
    text("switch ("),
    printExpression(node.discriminant, options),
    text(") {"),
    indent(concat([line(), concat(cases)])),
    line(),
    text("}"),
  ]);
}

function printReturnStatement(node, options) {
  if (!node.argument) {
    return text(options.semi ? "return;" : "return");
  }

  return concat([
    text("return "),
    printExpression(node.argument, options),
    text(options.semi ? ";" : ""),
  ]);
}

function printExpressionStatement(node, options) {
  return concat([
    printExpression(node.expression, options),
    text(options.semi ? ";" : ""),
  ]);
}

function printStatement(node, options) {
  switch (node.type) {
    case "VariableDeclaration":
      return printVariableDeclaration(node, options);
    case "FunctionDeclaration":
      return printFunctionDeclaration(node, options);
    case "ClassDeclaration":
      return printClassDeclaration(node, options);
    case "BlockStatement":
      return printBlockStatement(node, options);
    case "IfStatement":
      return printIfStatement(node, options);
    case "ForStatement":
      return printForStatement(node, options);
    case "WhileStatement":
      return printWhileStatement(node, options);
    case "TryStatement":
      return printTryStatement(node, options);
    case "ThrowStatement":
      return printThrowStatement(node, options);
    case "SwitchStatement":
      return printSwitchStatement(node, options);
    case "BreakStatement":
      return text(options.semi ? "break;" : "break");
    case "ContinueStatement":
      return text(options.semi ? "continue;" : "continue");
    case "ReturnStatement":
      return printReturnStatement(node, options);
    case "ExpressionStatement":
      return printExpressionStatement(node, options);
    case "ImportDeclaration":
      return printImportDeclaration(node, options);
    case "ExportNamedDeclaration":
      return printExportNamedDeclaration(node, options);
    case "ExportDefaultDeclaration":
      return printExportDefaultDeclaration(node, options);
    case "EmptyStatement":
      return text("");
    default:
      return fallbackPrint(node, options);
  }
}

/**
 * Format JavaScript source code with consistent style.
 *
 * @param {string} source Source code to format.
 * @param {{ quotes?: "single" | "double", semi?: boolean }} [options] Formatting options.
 * @returns {string} Formatted source code, terminated by one newline.
 */
export function format(source, options) {
  const ast = parse(source);
  const resolvedOptions = resolveOptions(options);

  const nonEmpties = ast.program.body.filter((stmt) => stmt.type !== "EmptyStatement");
  if (nonEmpties.length === 0) {
    return "";
  }

  const parts = [];
  nonEmpties.forEach((stmt, index) => {
    if (index > 0) {
      parts.push(line());
      const prev = nonEmpties[index - 1];
      if (
        (stmt.loc && prev.loc && stmt.loc.start.line - prev.loc.end.line > 1) ||
        stmt.type === "FunctionDeclaration" ||
        prev.type === "FunctionDeclaration" ||
        stmt.type === "ClassDeclaration" ||
        prev.type === "ClassDeclaration"
      ) {
        parts.push(line());
      }
    }
    parts.push(printStatement(stmt, resolvedOptions));
  });

  return `${renderDoc(concat(parts))}\n`;
}
